import java.util.*;
public class Q05_HospitalManagement {static class Person{String name;int age;Person(String n,int a){name=n;age=a;}}static class Doctor extends Person{String specialization;Doctor(String n,int a,String s){super(n,a);specialization=s;}}static class Surgeon extends Doctor{String surgeryType;Surgeon(String n,int a,String s,String t){super(n,a,s);surgeryType=t;}public String toString(){return "Name: "+name+"\nAge: "+age+"\nSpecialization: "+specialization+"\nSurgery Type: "+surgeryType;}}public static void main(String[]a){String[]p=new Scanner(System.in).nextLine().split(",",4);System.out.println(new Surgeon(p[0],Integer.parseInt(p[1]),p[2],p[3]));}}
